enum MarsType {
    // Add the fonts to the target and Info.plist (UIAppFonts); fall back to system faces otherwise.
    static func display(_ size: CGFloat) -> Font { .custom("IBM Plex Serif", size: size).weight(.light) }
    static func body(_ size: CGFloat = 17) -> Font { .custom("Inter", size: size) }
    static func mono(_ size: CGFloat = 13) -> Font { .custom("Geist Mono", size: size) }
}

enum MarsRadius {
    static let control: CGFloat = 4
    static let card: CGFloat = 12
}

struct PrimaryButtonStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .font(MarsType.body(16).weight(.medium))
            .frame(maxWidth: .infinity, minHeight: 48)
            .background(Color.brandButton.opacity(configuration.isPressed ? 0.85 : 1))
            .foregroundStyle(Color.brandOnButton)
            .clipShape(RoundedRectangle(cornerRadius: MarsRadius.control, style: .continuous))
    }
}
